c.python:
-- MySQL 8+
WITH t AS (
    SELECT DISTINCT user_id, item, created_at FROM Users
), q AS (
    SELECT user_id,
           DATEDIFF(created_at, LAG(created_at) OVER
               (PARTITION BY user_id ORDER BY created_at)) AS gap
    FROM t
)
SELECT DISTINCT user_id FROM q WHERE gap <= 7;

